package com.school.management.entity; import jakarta.persistence.*;import java.time.LocalDate;
@Entity public class FeePayment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long studentId; private Double amount; private String reference; private String method; private LocalDate paymentDate=LocalDate.now(); public FeePayment(){} public Long getId(){return id;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public Double getAmount(){return amount;} public void setAmount(Double v){amount=v;} public String getReference(){return reference;} public void setReference(String v){reference=v;} public String getMethod(){return method;} public void setMethod(String v){method=v;} public LocalDate getPaymentDate(){return paymentDate;} public void setPaymentDate(LocalDate v){paymentDate=v;} }
